(function(root){'use strict';const F=root.NutriFamily,E=root.NutriRegistrationEntry;const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function reportHTML(p,updated=false){const r=p.report,labels={kcal:['热量','kcal'],protein:['蛋白质','g'],carb:['碳水','g'],fat:['脂肪','g'],grams:['份量','g']};return `<h2>成员当日日报</h2><p class="family-report-identity"><strong>${esc(p.name)}</strong> · ${esc(p.date)}</p><p class="family-report-label">合成数据 · 只读规则统计${updated?' · 已按最新资料更新':''}</p>${r.entryCount?`<p><strong>${r.slotCount} 类餐次 · ${r.entryCount} 条记录</strong></p><p class="family-report-slots">早餐 ${r.slots.breakfast} · 午餐 ${r.slots.lunch} · 晚餐 ${r.slots.dinner} · 加餐 ${r.slots.snack}${r.unknownSlot?' · 餐次未知 '+r.unknownSlot:''}</p><table class="family-report-table"><caption>已记录条目的已知小计</caption><thead><tr><th scope="col">项目</th><th scope="col">已知小计</th><th scope="col">已知 / 未知条目</th></tr></thead><tbody>${Object.entries(labels).map(([k,[label,unit]])=>{const n=r.nutrients[k];return `<tr><th scope="row">${label}</th><td>${n.value===null?'未知':esc(n.value)+' '+unit}</td><td>${n.known} / ${n.unknown}</td></tr>`;}).join('')}</tbody></table>`:'<p>这天暂无餐食记录；营养与份量未知。</p>'}<p class="family-report-note">仅汇总实际已填数值，不从菜名推算。未知不按 0 计算；小计不是全天总摄入，未记录不代表未进食。</p>`;}
async function mount(){const page=document.querySelector('#family-app'),S=E.store;let state=null,active=true,busy=false,dirty=false,stale=false,unsub;const dirtyForms=new Set();
let statusTarget='[data-status-global]',dateStatusPrefix='';const guard=()=>active;const status=(s,reveal=false)=>{const node=page.querySelector(statusTarget)||page.querySelector('[data-status-global]');node.textContent=(statusTarget==='[data-date-status]'?dateStatusPrefix:'')+s;if(reveal)node.scrollIntoView?.({block:'nearest',behavior:'smooth'});};
function render(next){state=F.clone(next);stale=false;dirty=false;dirtyForms.clear();const f=state.health.family,p=f?F.projection(state):null;page.innerHTML=`<header><a href="intake.html">‹ 营养摄入</a><h1>合成家庭</h1><p>仅在本机演示；请勿输入真实姓名或健康资料。</p></header><p data-status-global role="status" aria-live="polite" aria-atomic="true"></p><p>家庭页面当前选择不会改变其他页面的沈先生本人视图。</p>${p?`<section><label>查看日期<input data-date type="date" value="${p.date}" aria-describedby="family-date-status"></label><p id="family-date-status" data-date-status role="status" aria-live="polite" aria-atomic="true"></p></section><section data-family-report aria-label="成员当日日报">${reportHTML(p)}</section><section><h2>家庭成员</h2><div class="family-members">${p.members.map(m=>`<article><strong>${esc(m.name)}</strong><small>${m.active?'可选成员':'归档保留'}</small>${m.active?`<button data-action="select" data-id="${m.id}" ${m.id===p.memberId?'disabled':''}>${m.id===p.memberId?'当前成员':'查看'}</button><details class="family-edit"><summary>编辑名称</summary><form data-form="rename" data-id="${m.id}"><label>改名<input name="name" maxlength="40" required value="${esc(m.name)}"></label><button>保存名称</button><p data-local-status role="status" aria-live="polite" aria-atomic="true"></p></form></details>${m.id==='self'?'':`<button data-action="delete" data-id="${m.id}">归档成员</button>`}`:`<button data-action="restore" data-id="${m.id}">恢复成员</button>`}</article>`).join('')}</div><p data-members-status role="status" aria-live="polite" aria-atomic="true"></p></section><section><h2>新增合成成员</h2><form data-form="add"><label>演示名称<input name="name" maxlength="40" required placeholder="例如：合成家人 A"></label><button>新增空白成员</button><p data-local-status role="status" aria-live="polite" aria-atomic="true"></p></form><p>不会继承沈先生的餐食、指标、随访或提醒。</p></section><section><h2>这天的餐食</h2>${p.meals.length?`<ul>${p.meals.map(m=>`<li>${esc(m.time)} ${esc(m.name)} · ${m.kcal===null||m.kcal===undefined?'热量未知':esc(m.kcal)+' kcal（合成）'}</li>`).join('')}</ul>`:'<p>暂无记录；未记录不代表未进食。</p>'}<form data-form="meal"><label>合成菜名<input name="name" required maxlength="40"></label><label>餐次<select name="slot"><option value="breakfast">早餐</option><option value="lunch">午餐</option><option value="dinner">晚餐</option><option value="snack">加餐</option></select></label><label>时间<input name="time" type="time" value="12:00" required></label><label><input name="consent" type="checkbox" required>确认仅为合成数据，归属 ${esc(p.name)} / ${p.date}</label><p>份量与营养未知，不从菜名推算。</p><button>确认记录</button><p data-local-status role="status" aria-live="polite" aria-atomic="true"></p></form></section>`:`<section><h2>保留本人，新增空白家庭</h2><p>首次启用保留当前沈先生资料快照，不改原本人记录。</p><button data-action="init">启用合成家庭</button></section>`}<button data-refresh>放弃未保存填写并刷新</button><footer><a href="settings.html">整个合成账号重置 / 回退说明</a><p>归档保留成员数据；家庭资料随整个账号重置。账户撤销能力以共享入口显示为准。</p></footer><nav class="family-bottom-nav" aria-label="主要页面"><a href="aiAgent.html">助手</a><a href="diet.html">饮食</a><a href="shop.html">商城</a><a href="health-calendar.html">记录</a><a href="profile.html">我的</a></nav>`;}
function disabled(v){page.querySelectorAll('button,input,select').forEach(x=>{if(!x.hasAttribute('data-refresh'))x.disabled=v||stale||E.hasPending();});}
async function execute(command){if(busy||stale||E.hasPending()||!state)return;const base=F.clone(state);let planned;try{planned=F.candidate(base,command);}catch(e){status(e.message);return;}busy=true;disabled(true);if(command.type==='date')status('正在切换查看日期，尚未确认保存；下方日报仍以其标注的成员与日期为准。');const context=F.context(base);
try{await E.execute({kind:'family:'+command.type,context,input:planned.input,guard,
run:({input,context})=>S.transact(d=>{F.mutate(d,input);return null;},{context,expectedRevision:context.revision,guard,reason:'family:'+command.type}),
onSuccess:receipt=>{if(!active)return;try{const saved=F.verify(base,planned.state,receipt);if(!F.same(saved,S.read()))throw Error('已有更新版本，请刷新核对；不清空当前填写');render(saved);const region=page.querySelector(statusTarget);const disclosure=region?.closest?.('details');if(disclosure)disclosure.open=true;status(receipt.persistent?'已保存到本机合成账号。':'仅本页临时保存；刷新或离开即丢失。',true);}catch(e){stale=true;status(e.message);}},
onError:e=>{if(active)status(e.message+'；填写保留，请在共享入口核对原操作。');},
reconcile:({state:now})=>({status:F.same(now,base)?'base':'changed',message:'请核对当前记录；记录匹配不替代原操作回执。'})});}catch(e){if(active)status(e.message+'；填写保留。');}finally{busy=false;if(active)disabled(false);}}
page.addEventListener('input',e=>{const form=e.target.closest?.('form');if(form?.dataset.form){dirty=true;dirtyForms.add(form);}});
page.addEventListener('submit',e=>{const form=e.target;if(!form.dataset.form)return;e.preventDefault();if(!form.reportValidity()||busy||stale||E.hasPending())return;if([...dirtyForms].some(other=>other!==form)&&!E.confirmLeave(true,'此保存会关闭其他表单尚未保存的填写。是否放弃其他填写并继续？'))return;const type=form.dataset.form;statusTarget=type==='rename'?'[data-form="rename"][data-id="'+form.dataset.id+'"] [data-local-status]':'[data-form="'+type+'"] [data-local-status]';let c={type,name:form.elements.name.value};if(type==='rename')c.memberId=form.dataset.id;if(type==='meal'){if(!form.elements.consent.checked)return;const id=root.crypto?.randomUUID?.();if(!id){status('安全标识不可用，未保存。');return;}c={type,row:{id:'family-'+id,accountId:'demo-shen',memberId:state.health.family.selected,date:state.health.family.date,synthetic:true,name:c.name,time:form.elements.time.value,slot:form.elements.slot.value,kcal:null,carb:null,protein:null,fat:null,grams:null,source:'user-demo-entry'}};}void execute(c);});
page.addEventListener('click',e=>{const link=e.target.closest('a[href]');if(link){if(!E.confirmLeave(dirty,'离开将放弃未保存填写，是否继续？'))e.preventDefault();return;}const b=e.target.closest('button');if(!b)return;if(b.hasAttribute('data-refresh')){if(busy||!E.confirmLeave(dirty,'刷新会放弃未保存填写。'))return;try{render(S.read());}catch(err){status(err.message);}return;}const type=b.dataset.action;if(!type||busy||stale||E.hasPending())return;if(!E.confirmLeave(dirty,'此操作将放弃未保存填写。'))return;if(type==='delete'&&!root.confirm('归档该合成成员？记录保留，可恢复。'))return;statusTarget=type==='init'?'[data-status-global]':'[data-members-status]';void execute({type,memberId:b.dataset.id});});
page.addEventListener('change',e=>{if(!e.target.hasAttribute('data-date')||!state)return;const dateStatus=page.querySelector('[data-date-status]');if(busy||stale||E.hasPending()){if(dateStatus)dateStatus.textContent=stale?'资料已更新，日期选择保留但尚未提交；日报以其最新标注的成员与日期为准。请明确刷新后再操作。':'操作尚未确认，暂不能再次切换日期；当前输入保留，不代表已保存。请先在共享入口核对原操作，日报以其标注为准。';return;}if(dirty&&!E.confirmLeave(true,'切换日期会放弃未保存填写。')){e.target.value=state.health.family.date;if(dateStatus)dateStatus.textContent='已取消切换日期；仍查看 '+state.health.family.date+'，各表单未保存填写已保留。';return;}statusTarget='[data-date-status]';dateStatusPrefix='日期查看（'+F.projection(state).name+' / '+(e.target.value||'未选择日期')+'）：';void execute({type:'date',date:e.target.value});});
root.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});root.addEventListener('pagehide',()=>{active=false;unsub?.();});
page.textContent='请先在共享入口确认合成演示…';try{await S.initialize({domains:['health'],guard});if(!active)return;render(S.read());unsub=S.subscribe(next=>{if(!active||busy||F.same(next,state))return;stale=true;const report=page.querySelector('[data-family-report]');if(report){try{report.innerHTML=next.health.family?reportHTML(F.projection(next),true):'<p>家庭资料已重置，请刷新后查看。</p>';}catch(e){report.textContent='日报暂不可用，请刷新核对账号与成员。';}}const message='资料已从其他页面更新，日报已核对最新资料；其他显示与填写保留，请明确刷新后再操作。';const globalStatus=page.querySelector('[data-status-global]');if(globalStatus)globalStatus.textContent=message;const dateStatus=page.querySelector('[data-date-status]');if(dateStatus)dateStatus.textContent='资料已更新，日期控件保留原选择；日报已按最新成员与日期更新，以日报标注为准。暂不能切换，请明确刷新后再操作；确认刷新会放弃草稿。';page.querySelectorAll('[data-local-status]').forEach(node=>{node.textContent='资料已更新，此表单的填写已保留但尚未保存，暂不能提交。请核对最新成员与日期，再用页面底部刷新按钮继续；确认刷新会放弃草稿。';});disabled(true);});}catch(e){page.textContent='家庭入口未就绪：'+e.message+'。请重新加载后通过共享入口恢复，不会另建账号。';}
}
E.register('family-ui',{buildId:'registration-web-v3-c1',mount});})(window);
